bomItems.itemLogicScript:
context.result = {
  plankId: 'TOP_01',
  name: 'Top Panel',
  width: context.inputs.boxWidth,
  height: context.inputs.boxDepth,
  thickness: context.inputs.materialThickness,
  materialCode: 'PLY_' + context.inputs.materialThickness + 'MM',
  grainDirection: 'along_width',
  edgeBanding: { top: '1mm', bottom: '1mm', left: '1mm', right: '1mm' }
};

context.result = {
  plankId: 'BOT_01',
  name: 'Bottom Panel',
  width: context.inputs.boxWidth,
  height: context.inputs.boxDepth,
  thickness: context.inputs.materialThickness,
  materialCode: 'PLY_' + context.inputs.materialThickness + 'MM',
  grainDirection: 'along_width',
  edgeBanding: { top: '1mm', bottom: '1mm', left: '1mm', right: '1mm' }
};

context.result = {
  plankId: 'LFT_01',
  name: 'Left Panel',
  width: context.inputs.boxHeight - (2 * context.inputs.materialThickness),
  height: context.inputs.boxDepth,
  thickness: context.inputs.materialThickness,
  materialCode: 'PLY_' + context.inputs.materialThickness + 'MM',
  grainDirection: 'along_height',
  edgeBanding: { top: '1mm', bottom: '1mm', left: '1mm', right: '1mm' }
};

context.result = {
  plankId: 'RGT_01',
  name: 'Right Panel',
  width: context.inputs.boxHeight - (2 * context.inputs.materialThickness),
  height: context.inputs.boxDepth,
  thickness: context.inputs.materialThickness,
  materialCode: 'PLY_' + context.inputs.materialThickness + 'MM',
  grainDirection: 'along_height',
  edgeBanding: { top: '1mm', bottom: '1mm', left: '1mm', right: '1mm' }
};

const backPanelThickness = context.itemDetails.defaultThickness || context.inputs.materialThickness / 3;
context.result = {
  plankId: 'BCK_01',
  name: 'Back Panel',
  width: context.inputs.boxWidth - (2 * context.inputs.materialThickness),
  height: context.inputs.boxHeight - (2 * context.inputs.materialThickness),
  thickness: backPanelThickness,
  materialCode: 'MDF_' + backPanelThickness + 'MM',
  grainDirection: 'along_width'
};

context.result = {
  name: 'Assembly Screws',
  quantity: context.itemDetails.quantityPerBox,
  unit: 'pieces',
  supplierCode: 'SCRW_4X30'
};
